import test from 'node:test';
import assert from 'node:assert/strict';
import { formatLabel, decoratedLabel } from '../src/format-label.js';
test('format valid label and preserve case', t => { assert.equal(formatLabel('MiXeD'), 'MiXeD'); t.diagnostic('BODY:format-valid'); });
test('reject blank label', t => { assert.throws(() => formatLabel('   '), /blank/); t.diagnostic('BODY:format-blank'); });
test('decorate with configured suffix', t => { assert.equal(decoratedLabel('hello'), 'hello!'); t.diagnostic('BODY:format-config'); });
test('trim surrounding whitespace and preserve case and internal whitespace', () => {
  assert.equal(formatLabel(' \t\nMiXeD Label\r\n '), 'MiXeD Label');
});
test('reject empty and mixed whitespace labels', () => {
  assert.throws(() => formatLabel(''), /blank/);
  assert.throws(() => formatLabel('\t\r\n '), /blank/);
});
test('decorate trimmed label with configured suffix', () => {
  assert.equal(decoratedLabel(' \tMiXeD '), 'MiXeD!');
});

